import{_ as i,o as l,c as t,a3 as r,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const u="/bilder/schueler/schulbesuch.png",h="/bilder/schueler/schulbesuch-grundschuldaten-schulbesuch-schueler.png",a="/bilder/schueler/schulbesuch-wechsel.png",c="/bilder/schueler/schulbesuch-wechsel-farben.png",k=JSON.parse('{"title":"Den bisherigen Schulbesuch und Schulwechsel erfassen","description":"","frontmatter":{"title":"Den bisherigen Schulbesuch und Schulwechsel erfassen","source_pageid":381,"source_revision":5091},"headers":[],"relativePath":"schild3/schueler/schulbesuch-schueler.md","filePath":"schild3/schueler/schulbesuch-schueler.md"}'),d={name:"schild3/schueler/schulbesuch-schueler.md"};function o(g,s,b,m,f,S){return l(),t("div",null,[...s[0]||(s[0]=[r('<h1 id="den-bisherigen-schulbesuch-und-schulwechsel-erfassen" tabindex="-1">Den bisherigen Schulbesuch und Schulwechsel erfassen <a class="header-anchor" href="#den-bisherigen-schulbesuch-und-schulwechsel-erfassen" aria-label="Permalink to &quot;Den bisherigen Schulbesuch und Schulwechsel erfassen&quot;">​</a></h1><p>Dokumentieren Sie die Herkunft, bisher besuchte Schulen und den Wechsel zu einer aufnehmenden Schule. Die Angaben zum vorherigen Schulbesuch werden auch für die Statistik benötigt.</p><p><a href="/bilder/schueler/schulbesuch.png"><img src="'+u+'" alt="Registerkarte &quot;Schulbesuch&quot;. Mit den Pfeilen werden Schulen in die Liste vorheriger Schulen übernommmen." loading="lazy"></a></p><p><em>Registerkarte &quot;Schulbesuch&quot;. Mit den Pfeilen werden Schulen in die Liste vorheriger Schulen übernommmen.</em></p><p>Auf dem Karteireiter <em>Schulbesuch</em> werden alle bisher besuchten Schulen aufgeführt.</p><p>Insbesondere die Schule aus dem letzten Schuljahr und die Art des Abschlusses werden hier vermerkt und in der Statistik abgefragt.</p><p>Bei Berufskollegs wird auf diesem Reiter nach dem <strong>höchsten allgemeinbildenden Abschluss</strong> gefragt, der von dem Schüler je erworben wurde. Hat der Schüler im letzten Schuljahr ein Berufskolleg besucht, dann wird hier auch die Eingabe der Fachklasse erwartet.</p><h2 id="herkunft-des-schulers" tabindex="-1">Herkunft des Schülers <a class="header-anchor" href="#herkunft-des-schulers" aria-label="Permalink to &quot;Herkunft des Schülers&quot;">​</a></h2><p>Mit dem <em>schwarzen Pfeil</em> bei <em>Art des Abschlusses</em> werden die Daten der Schule nach rechts in die Liste <em>aller bisher besuchten Schulen</em> übernommen.</p><p>Der Karteireiter <strong>Schulbesuch</strong> hat für die Erstellung der Statistik einige entscheidende Eintragungsfelder.</p><p>Der gesamte Bereich <em>Vor der Aufnahme besuchte Schule/Einrichtung/Sonstige Herkunftsarten</em> wird bei allen Schülern der Schule ausgewertet, die im letzten Schuljahr noch nicht an der eigenen Schule waren. Das bedeutet bei allen Neuaufnahmen und den Schülern, die zu Schuljahresbeginn &quot;zugezogen&quot; sind.</p>',11),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[e("strong",null,"Schulformspezifische Hinweise:")]),e("ul",null,[e("li",null,[e("p",null,[n("Eine Ausnahme bilden die "),e("strong",null,"Grundschulen"),n(': bei allen "Erstklässlern" bleibt dieser Bereich natürlich leer. Lediglich die '),e("strong",null,"Herkunftsart"),n(),e("em",null,"Einschulung"),n(" wird eingetragen. Stattdessen werden die Eintragungen zum Grundschulbesuch auf dem Karteireiter "),e("em",null,"Individualdaten II"),n(" ausgewertet.")])]),e("li",null,[e("p",null,[n("Für "),e("strong",null,"Sekundarschulen"),n(" sind Schulform und "),e("strong",null,"Allgemeine Herkunft"),n(" getrennte Schlüsselangaben. Wählen Sie die passende Bezeichnung im jeweiligen Feld. Verwenden Sie die aktuellen schulformspezifischen Erhebungsvorgaben.")])]),e("li",null,[e("p",null,[n("An "),e("strong",null,"Berufskollegs"),n(" und "),e("strong",null,"Weiterbildungskollegs"),n(" gibt es Schüler, die im vergangenen Schuljahr keine Schule besucht haben. Hier gelten die besonderen "),e("strong",null,[e("a",{href:"/schild3/schueler/eintragung-herkunft-am-bk-wbk-tutorial.html"},"Eintragungsmodalitäten")]),n("!")])])])],-1),e("div",{"data-hint-kind":"caution",class:"danger custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"caution","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"m10.3 4-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.7-3l-8-14a2 2 0 0 0-3.4 0Z"}),e("path",{d:"M12 9v4m0 4v.1"})]),n("Achtung")]),e("p",null,"Bitte beachten Sie, dass die Eintragungen an dieser Stelle nur im ersten Jahr des Schülers an der Schule ausgewertet werden. Die Angaben können danach zu Informationszwecken erhalten bleiben und brauchen nicht geändert zu werden.")],-1),r('<p>Um die Eintragungen für die Statistik näher zu erklären, dient die folgende Tabelle. Hier werden die Felder in SchILD-NRW und die Bezeichnungen von IT.NRW gegenübergestellt.</p><p>Bezeichnungen SchILD-NRW gegenüber IT.NRW</p><table tabindex="0"><thead><tr><th>SchILD-NRW Name des Feldes</th><th>IT.NRW-Statistik (Statkue.mdb)</th><th>Anzeigefilter in SchILD-NRW</th></tr></thead><tbody><tr><td>Allg. Herkunft des Schülers</td><td>Herkunftsschulform</td><td>Es wird auf die Schulform der Herkunftsschule gefiltert.</td></tr><tr><td>Versetzung</td><td>Herkunftsart</td><td>Filter auf zulässige Einträge der eigenen Schulform</td></tr><tr><td>Höchster allgemeinbildender Abschluss (BK,WBK) Art des Abschlusses (andere Schulen) von abgebender Schule</td><td>Abgangsart</td><td>Filter auf Schulform und Jahrgang der abgebenden Schule.<br>(Hier haben die BKs und WBKs eine feste programminterne Tabelle in SchILD-NRW wegen der Dopplungen in der Statkue.mdb)</td></tr><tr><td>Art des Abschlusses von eigener Schule</td><td>Abgangsart</td><td>Filter auf eigene Schulform und Jahrgang</td></tr></tbody></table><h2 id="grundschuldaten-eingeben" tabindex="-1">Grundschuldaten eingeben <a class="header-anchor" href="#grundschuldaten-eingeben" aria-label="Permalink to &quot;Grundschuldaten eingeben&quot;">​</a></h2><p><a href="/bilder/schueler/schulbesuch-grundschuldaten-schulbesuch-schueler.png"><img src="'+h+'" alt="Eingeben der Grundschuldaten." loading="lazy"></a></p><p><em>Eingeben der Grundschuldaten.</em></p><p>Auf dem Karteireiter <em>Schulbesuch</em> ist es an weiterführenden Schulen möglich, Daten der Grundschule für den Übergang an die Schule einzugeben.</p><p>Bitte klicken Sie dazu auf den Button <strong><a href="/schild3/schueler/grundschuldaten-eingeben-schueler-schulbesuch.html">Grundschuldaten eingeben</a></strong>.</p><h2 id="entlassung-von-eigener-schule" tabindex="-1">Entlassung von eigener Schule <a class="header-anchor" href="#entlassung-von-eigener-schule" aria-label="Permalink to &quot;Entlassung von eigener Schule&quot;">​</a></h2><p>Tragen Sie hier die Daten bei der Entlassung von der eigenen Schule ein. Dies betrifft <em>Abschluss</em> wie <em>Abgänger</em>.</p><p>Es empfiehlt sich, diese Eintragungen vor der Versetzung im Abschlussjahrgang zu tätigen. Allerdings können die Daten auch später noch nachgetragen werden, wenn die Schülerdatensätze schon im Abgänger- oder Abschlusskasten sind.</p>',11),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Die Eintragungen zu "),e("em",null,"Entlassdatum"),n(" und "),e("em",null,"Art des Abschlusses"),n(" sind statistikrelevant und somit verpflichtend auszufüllen.")])],-1),e("div",{"data-hint-kind":"important",class:"warning custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"important","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 7v6m0 4v.1"})]),n("Wichtig")]),e("p",null,"Bitte beachten Sie, dass an dieser Stelle nur Abschlüsse ausgewiesen werden, die an Ihrer Schule erworben wurden. Sollte ein Schüler an Ihrer Schule keinen neuen höherwertigeren Abschluss erlangt haben, so wird der letzte Abschluss hier nicht erneut eingegeben. Genauere Angaben finden Sie in den Schlüsseltabellen von IT.NRW")],-1),r('<h2 id="wechsel-zu-aufnehmender-schule" tabindex="-1">Wechsel zu aufnehmender Schule <a class="header-anchor" href="#wechsel-zu-aufnehmender-schule" aria-label="Permalink to &quot;Wechsel zu aufnehmender Schule&quot;">​</a></h2><p><a href="/bilder/schueler/schulbesuch-wechsel.png"><img src="'+a+'" alt="Eintragen einer aufnehmenden Schule." loading="lazy"></a></p><p><em>Eintragen einer aufnehmenden Schule.</em></p><p><a href="/bilder/schueler/schulbesuch-wechsel-farben.png"><img src="'+c+'" alt="Hier sind Schüler eines G9-Gymnasiums zu sehen, bei denen im Fenster &quot;Wechsel&quot; eine Schule der Sekundarstufe II eingetragen wurde (türkis). Die Farbe ist Grün, wenn die Aufnahme bestätigt wurde." loading="lazy"></a></p><p><em>Hier sind Schüler eines G9-Gymnasiums zu sehen, bei denen im Fenster &quot;Wechsel&quot; eine Schule der Sekundarstufe II eingetragen wurde (türkis). Die Farbe ist Grün, wenn die Aufnahme bestätigt wurde.</em></p><p>Die Angaben können Sie nutzen, um einen besseren Überblick zur Schulpflichtüberwachung zu haben.</p><p>Es werden Schüler eingetragen, die abgehen und zu einer anderen Schule wechseln, aber auch Schüler, die an der aktuellen Schule ihren Bildungsweg, auch mit Abschluss, beendet haben.</p><p>An <em>Grundschulen</em> und an <em>weiterführenden Schulen</em> in der Klasse 9 beziehungsweise der Klasse 10, bei denen einen Sekundarstufe-II-Schule eingetragen wurde, hat diese Eintragung noch einen weiteren Effekt:</p><p>Alle Schüler, bei denen eine aufnehmende Schule - beziehungsweise eine Schule der Sekundarstufe II - eingetragen ist, werden im mit einer <em>türkisen</em> Hintergrundfarbe dargestellt. Diese Hintergrundfarbe ändert sich dann nochmals auf <em>grün</em>, wenn der Haken bei &quot;Aufnahme bestätigt&quot; gesetzt wurde.</p><p>Dies soll eine optische Hilfe zur Kontrolle aller Schulanmeldungen sein.</p><h2 id="alle-bisher-besuchten-schulen" tabindex="-1">Alle bisher besuchten Schulen <a class="header-anchor" href="#alle-bisher-besuchten-schulen" aria-label="Permalink to &quot;Alle bisher besuchten Schulen&quot;">​</a></h2><p>Zu Informationszwecken können hier alle bisher besuchten Schulen aufgelistet werden.</p><p>Die Eintragung von Links (Grundschulbesuch, andere vorherige Schulen) im oberen Bereich (Entlassung von eigener Schule) kann hierher mit dem &quot;schwarzen Pfeil&quot; übernommen werden.</p><p>Zusätzliche Eintragungen können über das Plussymbol <strong>+</strong> ergänzt werden.</p><p>Die Auswahllisten der Abschlussarten berücksichtigen das <strong>Entlassdatum</strong>. Tragen Sie deshalb zuerst die zutreffenden Schulbesuchsdaten ein, wenn ein erwarteter Abschluss nicht angeboten wird.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Schulbesuch_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5091.</p>',17)])])}const w=i(d,[["render",o]]);export{k as __pageData,w as default};
